td.div:

Fecha programada: ${object.schedule_date.strftime('%d/%m/%Y') if object.schedule_date else 'No especificada'}

Solicitud: ${object.name}
                                % if object.equipment_id:

Equipo: ${object.equipment_id.name}
                                % endif
                                % if object.equipment_line_ids:

Equipos a mantener:

                                    % for line in object.equipment_line_ids:

${line.equipment_id.name}
                                    % endfor

                                % endif
                                % if object.description:

Descripción:

${object.description}
                                % endif

tr.td:
% if object.company_id.phone:
Tel: ${object.company_id.phone}

% endif
% if object.company_id.email:
Email: ${object.company_id.email}

% endif
% if object.company_id.website:
Web: ${object.company_id.website}
% endif
